interface Clock { fun now(): Long }
class FakeClock(var t: Long) : Clock {
    override fun now() = t
}

class SessionManager(private val clock: Clock) {
    private val start = clock.now()
    fun expired() = clock.now() - start > 1000
}

fun main() {
    val clock = FakeClock(0)
    val s = SessionManager(clock)
    print(s.expired())
    clock.t = 1500
    println(" " + s.expired())
}

