class Api { init { created++ } }

class Container {
    val scopedApi by lazy { Api() }
    fun unscopedApi() = Api()
}

fun main() {
    val c = Container()
    repeat(3) { c.scopedApi }
    println(created)
    repeat(3) { c.unscopedApi() }
    println(created)
}

